import{_ as s}from"./chunks/频率统计.CaUx5NaU.js";import{_ as e}from"./chunks/累计统计.ONMYaXP8.js";import{c as a,Q as d,j as n,m as r}from"./chunks/framework.DOi4mjdC.js";const _=JSON.parse('{"title":"Histograms","description":"","frontmatter":{},"headers":[{"level":1,"title":"Histograms","slug":"histograms"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Reg矢量计算/直方图计算/Histograms.md","filePath":"api/SIMD-API/基础API/Reg矢量计算/直方图计算/Histograms.md"}'),l={name:"api/SIMD-API/基础API/Reg矢量计算/直方图计算/Histograms.md"};function i(p,t,o,g,c,h){return d(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="histograms" tabindex="-1">Histograms <a class="header-anchor" href="#histograms" aria-label="Permalink to &quot;Histograms&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>x</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>x</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>对直方图数据进行统计，在目的操作数dstReg的基础数据上加上源操作数srcReg数据的统计结果，包括数据的频率统计和累计统计。</p><ul><li><p>频率统计</p><p>如下图所示，在低位模式下，dstReg（即 dst0）用于统计srcReg中[0-127]范围内（前半部分）各个值的出现频率；而在高位模式下，dstReg（即dst1）则统计[128-255]范围内（后半部分）的频率。dst0和dst1中的第n位（bit）表示srcReg中数值n的出现次数，并在原始dstReg数据的基础上进行累加。</p><p><strong>图 1</strong> 频率统计<br><img src="'+s+'" alt="" title="频率统计"></p></li><li><p>累计统计</p><p>如下图所示，在低位模式下，目的寄存器dstReg（即dst0）会统计源寄存器srcReg中值落在低位区间[0-127]的数据分布情况；在高位模式下，目的寄存器dstReg（即dst1）则会统计srcReg中值落在高位区间[128-255]的数据分布情况。在dst0 和dst1中，第n位的数据表示srcReg中从0到n的所有数值在对应区间中出现的总频率。最终，统计结果会在目的寄存器原始数据的基础上进行累加。</p><p><strong>图 2</strong> 累计统计<br><img src="'+e+`" alt="" title="累计统计"></p></li></ul><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T = DefaultType, typename U = DefaultType, HistogramsBinType mode, HistogramsType type, typename S, typename V&gt;</span></span>
<span class="line"><span>__simd_callee__ inline void Histograms(V&amp; dstReg, S&amp; srcReg, MaskReg&amp; mask)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>源操作数的数据类型。 Ascend 950PR/Ascend 950DT，支持的数据类型为：uint8_t</td></tr><tr><td>U</td><td>目的操作数的数据类型。 Ascend 950PR/Ascend 950DT，支持的数据类型为：uint16_t</td></tr><tr><td>mode</td><td>HistogramsBinType枚举类型，用于控制统计src的低位区间[0-127]（前半部分）或高位区间[128-255]（后半部分）的数据。VL长度为256Byte，dst数据类型为uint16_t，一个dst可以存储128个数据，因此需要两个dst。 BIN0表示低位模式，统计src中[0-127]范围内的数据写入dst0。BIN1表示高位模式，统计src中[128-255]范围内的数据写入dst1。</td></tr><tr><td>type</td><td>HistogramsType 枚举类型，表示统计模式。FREQUENCY：频率统计模式，统计src中[0, 255]每个数的数量。每个dst有128个元素，其中dst0中每个元素对应src中[0, 127]每个元素的累加个数，dst1中每个元素对应src中[128,255]每个元素的累加个数。ACCUMULATE：累计统计模式，统计src中x&lt;=0、x&lt;=1、x&lt;=2、x&lt;=3......x&lt;=254、x&lt;=255每个区间的元素个数。每个dst有128个元素，其中dst0中每个元素对应src中[0, 127]每个元素区间累加个数，dst1中每个元素对应src中[128，255]每个元素区间累加个数。</td></tr><tr><td>S</td><td>目的操作数RegTensor类型，由编译器自动推导，用户不需要填写。</td></tr><tr><td>V</td><td>源操作数RegTensor类型，由编译器自动推导，用户不需要填写。</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dstReg</td><td>输出</td><td>目的操作数。 类型为RegTensor。</td></tr><tr><td>srcReg</td><td>输入</td><td>源操作数。 类型为RegTensor。</td></tr><tr><td>mask</td><td>输入</td><td>源操作数元素操作的有效指示，详细说明请参考MaskReg。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>无</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, typename U&gt;</span></span>
<span class="line"><span>__simd_vf__ inline void HistogramsVF(__ubuf__ U* dstAddr, __ubuf__ T* srcAddr, uint32_t oneRepeatSize, uint16_t repeatTimes, AscendC::Reg::HistogramsBinType mode, AscendC::Reg::HistogramsType type)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;T&gt; srcReg;</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;U&gt; dstReg;</span></span>
<span class="line"><span>    AscendC::Reg::MaskReg mask0 = AscendC::Reg::CreateMask&lt;T&gt;();</span></span>
<span class="line"><span>    AscendC::Reg::MaskReg mask1 = AscendC::Reg::CreateMask&lt;T&gt;();</span></span>
<span class="line"><span>    for (uint16_t i = 0; i &lt; repeatTimes; ++i){</span></span>
<span class="line"><span>        AscendC::Reg::LoadAlign(srcReg, srcAddr + oneRepeatSize * i);</span></span>
<span class="line"><span>        AscendC::Reg::Histograms&lt;T, U, mode, type&gt;(dstReg, srcReg, mask0);</span></span>
<span class="line"><span>        AscendC::Reg::StoreAlign(dstAddr, dstReg, mask1);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,19)])])}const A=a(l,[["render",i]]);export{_ as __pageData,A as default};
